@startuml

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + emailAddress : string
}

class PickupRequest {
  + streetAddress : string
  + description : string
  + pickupTime : time
}

class Item {
  + description : string
  + dimensions : string
  + weight : float
}

class NonPerishableFood {}

class SecondHandArticle {
  + description : string
  + rfidTag : string
}

class Category {
  + name : string
}

class Vehicle {
  + storageSpace : float
}

class PickupRoute {
  + date : date
}

class VolunteerDriver {
  + name : string
}

class H2SLocation {
  + city : string
}

class H2SEmployee {
  + name : string
}

class Client {
  + homeAddress : string
}

class Delivery {
  + date : date
}

Resident "1" -- "*" PickupRequest : schedules
PickupRequest "1" -- "1" Item
Item <|-- NonPerishableFood
Item <|-- SecondHandArticle
SecondHandArticle "*" -- "1" Category : assigned to
SecondHandArticle "*" -- "0..1" Client : delivered to
H2SLocation "1" -- "*" Resident : serves
H2SLocation "1" -- "*" H2SEmployee : employs
H2SLocation "1" -- "*" VolunteerDriver : employs
H2SLocation "1" -- "*" Vehicle : owns
H2SLocation "1" -- "1" PickupRoute : manages
PickupRoute "1" -- "1" Vehicle : assigned to
PickupRoute "1" -- "1..*" VolunteerDriver : driven by
PickupRoute "1" -- "*" PickupRequest : includes
PickupRequest "1" -- "1" Vehicle : uses
VolunteerDriver "1" -- "*" Delivery : performs
Client "1" -- "*" Delivery : receives
Delivery "1" -- "1" SecondHandArticle : contains

@enduml

